#define pb push_back
#define ff first
#define ss second

typedef long long ll;
const int MAXN = 50;

pair<bool, ll> ispot(ll x) {
    ll e = 0;
    while (!(x % 2)) {
        x /= 2;
        e++;
    }
    return {x == 1, e};
}

int n;
ll P[MAXN + 1], DOS[MAXN + 1];
vector<ll> X;
pair<bool, ll> E;

bool test(ll K) {
    vector<ll> V = X, U;

    forn(i, MAXN) {
        forr(j, K, P[i]) V.pb(DOS[i]);
    }

    if (V.size() > static_cast<size_t>(P[0])) return false;

    forn(i, MAXN) {
        forr(j, P[i + 1], min(P[i], K)) U.pb(DOS[i + 1]);
    }

    sort(U.begin(), U.end());
    sort(V.begin(), V.end());

    while (!U.empty() && !V.empty()) {
        if (V.back() <= U.back()) {
            U.pop_back();
            V.pop_back();
        } else {
            break;
        }
    }

    return V.empty();
}

