    DOS[0] = 1;
    forr(i, 1, MAXN + 1) DOS[i] = DOS[i - 1] * 2;

    while (cin >> n) {
        fill(P, P + MAXN + 1, 0);
        X.clear();

        forn(i, n) {
            ll x;
            cin >> x;
            E = ispot(x);
            if (E.ff) P[E.ss]++;
            else X.pb(x);
        }

        ll M = P[0];
        forn(i, MAXN) {
            while (P[i] > M) {
                X.pb(DOS[i]);
                P[i]--;
            }
            M = P[i];
        }

        ll L = 0, r = P[0] + 1;
        ll R = P[0];

        while (r - L > 1) {
            ll m = (L + r) / 2;
            if (test(m)) r = m;
            else L = m;
        }

        if (R - L) {
            forr(i, L, R) {
                if (i > L) cout << ' ';
                cout << i + 1;
            }
        } else {
            cout << -1;
        }
        cout << '\n';
    }

    return 0;
}

